using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;

static class BuiltinTests {
 public static int Run(string source,string expectedWave,string hxf,string folder){Directory.CreateDirectory(folder);var cases=new List<object>();int failed=0;Action<string,Action> test=(name,body)=>{try{body();cases.Add(new{name=name,status="PASS"});}catch(Exception e){failed++;cases.Add(new{name=name,status="FAIL",error=e.Message});}};Action<bool> need=b=>{if(!b)throw new Exception("Comprobación fallida");};NamCapture capture=null;FirmwareFile firmware=null;
  test("attached_capture_sha_and_lite_validation",()=>{capture=NamCapture.Read(source,-5);need(capture.Hash=="3b7f55625b0d7942bdc03955d18104e6867c40dd4b6a3eecea39c78b4d985af9"&&capture.Name=="Developed by Conr4d"&&capture.OutputDb==-5);});
  test("independent_csharp_converter_matches_upstream_golden",()=>{File.WriteAllBytes(Path.Combine(folder,"converted-csharp.wav"),capture.Wave);byte[] expected=File.ReadAllBytes(expectedWave);if(!capture.Wave.SequenceEqual(expected)){var diff=Enumerable.Range(0,Math.Min(expected.Length,capture.Wave.Length)).Where(i=>expected[i]!=capture.Wave[i]).ToArray();throw new Exception("Diferencias en "+diff.Length+" bytes; primera en "+(diff.Length==0?-1:diff[0]));}});
  test("conr4d_hxf_passes_all17_checksums_and_recovery_guards",()=>{firmware=FirmwareFile.Read(hxf);need(firmware.Hash==PortableRuntime.CustomHash&&!firmware.IsOfficial&&!firmware.IsWithdrawn&&firmware.ImageCount==17);});
  test("embedded_model_zero_matches_source_at_minus5_byte_exact",()=>{byte[] raw=firmware.Inflated;int at=24;for(int image=0;image<2;image++)at=checked(at+36+(int)FirmwareFile.BE(raw,at+16)*4);int end=at+36+checked((int)FirmwareFile.BE(raw,at+16)*4),body=at+36+512;int position=body+1536,found=0;byte[] payload=NamCapture.AudioPayload(capture.Wave);while(position+12<=end){uint tag=FirmwareFile.LE(raw,position),n=FirmwareFile.LE(raw,position+4),address=FirmwareFile.LE(raw,position+8);position+=12;if(tag==0)break;uint size=(tag==1||tag==2||tag==7||tag==8)?0:tag==3?(n+n%2)*2:(tag==4||tag==9||tag==10)?n*4:tag==5?(n+n%2)*6:tag==6?n*8:uint.MaxValue;need(size!=uint.MaxValue&&size<=end-position);if(tag==4&&address==0x30a700){need(n==2048);for(int word=0;word<2048;word++)need(FirmwareFile.LE(raw,position+word*4)==FirmwareFile.LE(payload,(2047-word)*4));found++;}position+=checked((int)size);}need(found==1);});
  File.WriteAllText(Path.Combine(folder,"results.json"),new JavaScriptSerializer().Serialize(new{status=failed==0?"PASS_LOCAL_ONLY":"FAIL",cases=cases,USB_opened=false,firmware_installed=false,physical_audio_verified=false}));return failed==0?0:1;
 }
}
